N=17; mid=N//2; g=[[0]*N for _ in range(N)]
for r in range(mid+1):
    g[r][mid-r]=2; g[r][mid+r]=2
for j in range(20):
    r0=3+2*j; c0=mid-1-2*j
    for r in range(max(r0,-c0),N):
        c=c0+(r-r0)
        if 0<=c<N and g[r][c]==0: g[r][c]=1
print('\n'.join(' '.join(map(str,row)) for row in g))
